package com.mohymods.kingdomsmp.gametest;
import com.mohymods.kingdomsmp.building.*;
import com.mohymods.kingdomsmp.economy.*;
import com.mohymods.kingdomsmp.network.*;
import com.mohymods.kingdomsmp.npc.*;
import com.mohymods.kingdomsmp.persistence.*;
import com.mohymods.kingdomsmp.profession.*;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.gametest.framework.*;
import net.minecraft.server.level.*;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.*;
import net.neoforged.neoforge.gametest.*;
/** Actual paid-plan lifecycle/enrollment. Explicit seeded tier boundaries and funds do not prove earned higher tiers. */
@GameTestHolder("kingdom_smp_premises_tests") @PrefixGameTestTemplate(false)
public final class ProfessionPremisesRuntimeTests {
 @GameTest(template="empty",timeoutTicks=20000) public static void remainingNinePremises(GameTestHelper h)throws Exception{
  h.getLevel().getServer().tickRateManager().setTickRate(200);
  if(ConstructionService.store(h.getLevel().getServer()).projects().stream().filter(p->ProfessionPremises.contains(p.blueprint())&&p.phase()==ConstructionStore.Phase.COMPLETE).count()==9){restart(h);return;}
  TownHallRuntimeTests.newWorldLoop(h,()->{try{new Walk(h).next();}catch(Exception failure){h.fail(failure.toString());}});
 }
 static final class Walk {
  final GameTestHelper h;final ServerLevel level;final ServerPlayer buyer,peer;final ConstructionStore.Project hall;final EconomyStore money;int index;long sequence=80000;ConstructionStore.Project project;ConstructionBlueprint blueprint;ProfessionPremises.Definition definition;Rotation rotation;
  Walk(GameTestHelper h)throws Exception{this.h=h;level=h.getLevel();hall=ConstructionService.lodge(level.getServer());buyer=level.getServer().getPlayerList().getPlayer(hall.owner());peer=level.getServer().getPlayerList().getPlayers().stream().filter(p->p!=buyer).findFirst().orElseThrow();money=CommerceService.store(level.getServer());ClaimRuntimeTests.publicResidentAccess(level,buyer.getUUID());}
  void counter(){var at=hall.origin().offset(BlueprintRegistry.get(hall.blueprint(),1).home());buyer.moveTo(at.getX()+.5,at.getY(),at.getZ()-1.5);peer.moveTo(at.getX()-.5,at.getY(),at.getZ()-1.5);level.getChunkSource().move(buyer);level.getChunkSource().move(peer);CommerceService.openResident(buyer,(ReeveEntity)level.getEntity(hall.npc()));CommerceService.openResident(peer,(ReeveEntity)level.getEntity(hall.npc()));}
  CommerceView review(ServerPlayer p,String id){return CommerceService.handle(p,new CommerceRequest(++sequence,1,0,id,1,CommerceRequest.NONE));}
  void confirm(ServerPlayer p,CommerceView q,String id){CommerceService.handle(p,new CommerceRequest(++sequence,2,0,id,1,q.review()));}
  void refused(Runnable action){boolean denied=false;try{action.run();}catch(IllegalArgumentException|IllegalStateException expected){denied=true;}h.assertTrue(denied,"Stale native review must refuse");}
  void next()throws Exception{
   if(index==9){finish();return;}definition=ProfessionPremises.definitions().get(index);String id=definition.id().toString();counter();money.adminSet(UUID.randomUUID(),new UUID(0,0),buyer.getUUID(),50000,"Explicit isolated premises boundary funds");money.adminSet(UUID.randomUUID(),new UUID(0,0),peer.getUUID(),50000,"Explicit isolated competing buyer funds");
   DimensionTravelRuntimeTests.seed(level.getServer(),definition.tier()-1);boolean denied=false;try{review(buyer,id);}catch(IllegalStateException expected){denied=true;}h.assertTrue(denied&&money.purchase(id).isEmpty()&&money.balance(buyer.getUUID())==50000,"Approved prerequisite tier refuses ordinary purchase without charging");
   DimensionTravelRuntimeTests.seed(level.getServer(),definition.tier());var first=review(buyer,id);var rival=review(peer,id);h.assertTrue(first.reviewing()&&rival.reviewing(),"Both actual peers can review one available plan at its approved gate");confirm(buyer,first,id);refused(()->confirm(peer,rival,id));refused(()->confirm(buyer,first,id));h.assertTrue(money.balance(buyer.getUUID())==50000-definition.price()&&money.balance(peer.getUUID())==50000&&money.purchase(id).orElseThrow().buyer().equals(buyer.getUUID()),"First valid buyer charged once; stale/rival confirmation cannot buy sold plan");
   project=ConstructionService.store(level.getServer()).reward("market:"+id).orElseThrow();ConstructionService.select(buyer,project.id());buyer.getInventory().clearContent();buyer.getInventory().selected=0;var claim=ConstructionService.review(buyer,1);ConstructionService.confirm(buyer,claim.nonce(),2);h.assertTrue(buyer.getMainHandItem().is(KingdomBlueprints.item(definition.id()))&&ConstructionService.heldPlan(buyer,ConstructionService.store(level.getServer()).get(project.id())),"Unique physical plan authenticates canonical entitlement");
   blueprint=BlueprintRegistry.get(definition.id(),1);rotation=Rotation.values()[index%4];var site=hall.origin().offset(80+index%3*32,0,40+index/3*32);
   for(int x=(site.getX()-3)>>4;x<=(site.getX()+blueprint.width(rotation)+3)>>4;x++)for(int z=(site.getZ()-4)>>4;z<=(site.getZ()+blueprint.depth(rotation)+3)>>4;z++){level.getChunk(x,z);var pos=new BlockPos(x*16,site.getY(),z*16);ClaimRuntimeTests.ftbClaim(buyer,pos);ClaimRuntimeTests.opacClaim(level,buyer.getUUID(),pos);}
   for(var pos:BlockPos.betweenClosed(site.offset(-2,-1,-3),site.offset(blueprint.width(rotation)+2,-1,blueprint.depth(rotation)+2)))level.setBlock(pos,Blocks.STONE.defaultBlockState(),18);
   buyer.moveTo(site.getX()-2,site.getY()+1,site.getZ());level.getChunkSource().move(buyer);var preview=ConstructionService.preview(buyer,site,rotation);h.assertTrue(preview.denial().isBlank(),"Authenticated complete footprint is claim-valid: "+preview.denial());
   if(index==0){var obstacle=site.offset(7,4,7);level.setBlock(obstacle,Blocks.STONE.defaultBlockState(),3);h.assertTrue(!ConstructionService.preview(buyer,site,rotation).denial().isBlank(),"Full building envelope refuses existing obstacle without consuming plan");level.setBlock(obstacle,Blocks.AIR.defaultBlockState(),3);ConstructionService.preview(buyer,site,rotation);}
   var placement=ConstructionService.view(buyer,1,false,"");ConstructionService.confirm(buyer,placement.review(),4);var start=ConstructionService.review(buyer,7);ConstructionService.confirm(buyer,start.nonce(),8);
   var builder=level.getEntity(BuilderHutSavedData.get(level.getServer()).hut().orElseThrow().npcId());var post=blueprint.workPost(site,rotation);builder.moveTo(post.getX()+.5,post.getY(),post.getZ()+.5);build();
  }
  void build(){h.runAfterDelay(1,()->{try{var store=ConstructionService.store(level.getServer());for(int i=0;i<4&&store.get(project.id()).phase()==ConstructionStore.Phase.BUILDING;i++)ConstructionService.step(level.getServer(),project.id());if(store.get(project.id()).phase()!=ConstructionStore.Phase.COMPLETE){build();return;}h.runAfterDelay(20,()->{try{verified();}catch(Exception failure){h.fail(failure.toString());}});}catch(Exception failure){h.fail(failure.toString());}});}
  void verified()throws Exception{
   var saved=ConstructionService.store(level.getServer()).get(project.id());verify(h,saved);h.assertTrue(ConstructionService.structureIntact(level,hall),"Existing Town Hall remains untouched");
   var student=index<3?buyer:index<6?peer:thirdStudent();
   var home=saved.origin().offset(blueprint.rotate(blueprint.home(),rotation));student.moveTo(home.getX()+.5,home.getY(),home.getZ()-1.5);level.getChunkSource().move(student);CommerceService.openResident(student,(ReeveEntity)level.getEntity(saved.npc()));var learn=ProfessionService.review(student,"learn:"+definition.profession().id());ProfessionService.confirm(student,learn.nonce());h.assertTrue(money.professions(student.getUUID()).isActive(definition.profession())&&money.professions(student.getUUID()).track(definition.profession()).xp()==0,"Actual staffed premises enable normal enrollment without invented quests or rank");
   boolean denied=false;try{ProfessionService.review(student,"quest:"+definition.profession().questId(ProfessionRank.APPRENTICE,1));}catch(IllegalArgumentException|IllegalStateException expected){denied=true;}h.assertTrue(denied,"Event packets cannot grant unavailable or delivery-only objectives");index++;next();
  }
  ServerPlayer thirdStudent()throws Exception{var id=UUID.nameUUIDFromBytes("PremisesThirdStudent".getBytes(java.nio.charset.StandardCharsets.UTF_8));var p=level.getServer().getPlayerList().getPlayer(id);return p==null?ClaimRuntimeTests.vanillaPlayer(level,id,"ThirdStudent"):p;}
  void finish()throws Exception{
   var projects=ConstructionService.store(level.getServer()).projects().stream().filter(p->ProfessionPremises.contains(p.blueprint())).toList();h.assertTrue(projects.size()==9&&projects.stream().map(ConstructionStore.Project::npc).distinct().count()==9,"One permanent construction/resident record per profession");
   CommerceService.verifyReceipt(buyer);CommerceService.verifyReceipt(peer);var data=level.getServer().getWorldPath(net.minecraft.world.level.storage.LevelResource.ROOT).resolve("data");h.assertTrue(ConstructionStore.open(data).projects().containsAll(projects)&&EconomyStore.open(data).purchases().size()==9,"Exact native/canonical journal reopen preserves nine unique buyers and project records");h.succeed();com.mojang.logging.LogUtils.getLogger().info("PROFESSION_PREMISES_PREPARED: all9paid authenticated rotated plans, real Aldric placements, furnished staffed premises/enrollment, tier/collision/stale buyer checks; explicit tier/funds/wait fixtures, no profession XP injected");
  }
 }
 static void verify(GameTestHelper h,ConstructionStore.Project p){var level=h.getLevel();var b=BlueprintRegistry.get(p.blueprint(),1);h.assertTrue(ConstructionService.structureIntact(level,p),"Complete maintained rotated profession building "+p.blueprint()+"; prefix="+ConstructionService.verifyPrefix(level,p)+",loaded="+ConstructionService.loaded(level,p)+",placed="+p.placed()+"; "+b.blocks(p.rotation()).stream().filter(c->!ConstructionBlueprint.matches(level.getBlockState(p.origin().offset(c.offset())),c.state())).limit(4).map(c->c.offset()+" expected="+c.state()+" actual="+level.getBlockState(p.origin().offset(c.offset()))).toList());for(var cell:b.blocks(p.rotation())){var at=p.origin().offset(cell.offset());h.assertTrue(level.getBlockState(at).canSurvive(level,at),"Supported native workstation/furnishing "+at);}var npc=level.getEntity(p.npc());h.assertTrue(npc instanceof ReeveEntity&&npc.getType()==KingdomNpcs.RESIDENT.get()&&npc.getName().getString().equals(BlueprintRegistry.defaultResident(p.blueprint()))&&ConstructionService.registeredReeve((ReeveEntity)npc),"Exactly assigned named authenticated profession NPC "+p.blueprint()+" expected="+p.npc()+" actual="+npc);}
 static void whenResidents(GameTestHelper h,java.util.List<ConstructionStore.Project> projects,Runnable action){waitResidents(h,projects,action,0);}
 static void waitResidents(GameTestHelper h,java.util.List<ConstructionStore.Project> projects,Runnable action,int attempts){h.runAfterDelay(20,()->{if(attempts<30&&projects.stream().anyMatch(p->h.getLevel().getEntity(p.npc())==null)){waitResidents(h,projects,action,attempts+1);return;}action.run();});}
 static void restart(GameTestHelper h)throws Exception{
  var level=h.getLevel();var projects=ConstructionService.store(level.getServer()).projects().stream().filter(p->ProfessionPremises.contains(p.blueprint())).toList();for(var p:projects){var bounds=ConstructionService.bounds(p);for(int x=((int)bounds.minX)>>4;x<=((int)bounds.maxX)>>4;x++)for(int z=((int)bounds.minZ)>>4;z<=((int)bounds.maxZ)>>4;z++)level.getChunk(x,z);}
  var buyer=ClaimRuntimeTests.vanillaPlayer(level,projects.getFirst().owner(),projects.getFirst().ownerName());var first=ConstructionService.lodge(level.getServer());var hub=first.origin().offset(119,0,79);buyer.moveTo(hub.getX()+.5,hub.getY()+1,hub.getZ()+.5);level.getChunkSource().move(buyer);
  whenResidents(h,projects,()->{try{for(var p:projects)verify(h,p);if(Boolean.getBoolean("kingdom.testSmithProduction")&&java.nio.file.Files.exists(BlacksmithRepairRuntime.proof(buyer))){BlacksmithRepairRuntime.resume(h,buyer);return;}var money=CommerceService.store(level.getServer());var peer=ConstructionService.store(level.getServer()).projects().stream().filter(p->p.blueprint().equals(BlueprintRegistry.HUT)).findFirst().orElseThrow().owner();for(int n=0;n<9;n++){var role=ProfessionPremises.definitions().get(n).profession();var identity=n<3?buyer.getUUID():n<6?peer:UUID.nameUUIDFromBytes("PremisesThirdStudent".getBytes(java.nio.charset.StandardCharsets.UTF_8));h.assertTrue(money.professions(identity).isActive(role)&&money.professions(identity).track(role).xp()==0&&money.professions(identity).active().size()==3,"All nine original enrollments and three-slot limits persist without invented XP");}h.assertTrue(projects.stream().map(ConstructionStore.Project::npc).distinct().count()==9&&money.purchases().size()==9,"Restart retains all unique original native resident UUIDs and purchases");if(Boolean.getBoolean("kingdom.testSmithProduction")){BlacksmithProductionRuntime.run(h,buyer);BlacksmithRepairRuntime.prepare(h,buyer);return;}h.succeed();com.mojang.logging.LogUtils.getLogger().info("PROFESSION_PREMISES_RESTART_PASSED: all9original structures/resident UUIDs/enrollment/purchases restored in real second JVM; no duplicate construction or service reward");}catch(Exception failure){h.fail(failure.toString());}});
 }
}
